// it.ktrdiff.core.normalize.VolatileProperties — transformation <info> properties that Spoon
// rewrites on every save (PDI 9.4, docs/fixture-issues.md issue 5). Still detected and shown in
// Advanced mode; flagged volatile so Quick hides them and strict fixture matching skips them.

const INFO_PROPERTIES: ReadonlySet<string> = new Set([
  'name', // Spoon sets it to the file name on save
  'directory', // repository path of the saved file
  'created_user',
  'created_date',
  'modified_user',
  'modified_date',
  'trans_version',
  'key_for_session_key', // session key blob, regenerated by Spoon
  'is_key_private',
]);

export function isVolatileInfoProperty(propertyName: string | null): boolean {
  return propertyName !== null && INFO_PROPERTIES.has(propertyName);
}
